<section class="dist-page school-module"><header class="dist-head"><div><h2><?= e($s['name']) ?></h2><p><?= e($s['address']) ?> · WA <?= e($s['whatsapp']) ?></p></div><?php if (can('sekolah.edit')): ?><a class="btn" href="<?= e(url('/admin/sekolah/'.$s['id'].'/edit')) ?>">Edit Sekolah</a><?php endif; ?></header>
<div class="stats-grid"><div class="card"><small>Jumlah siswa</small><h3><?= number_format($s['daily_portions']) ?></h3></div><div class="card"><small>Jumlah menu</small><h3><?= number_format($s['menu_count']) ?></h3></div><div class="card"><small>Porsi direncanakan hari ini</small><h3><?= number_format($s['planned']) ?></h3></div><div class="card"><small>Porsi telah dikirim/lebih lanjut</small><h3><?= number_format($s['sent']) ?></h3></div><div class="card"><small>Pengiriman hari ini</small><h3><?= (int)($stats['today_count']??0) ?></h3></div><div class="card"><small>Dalam pembuatan / perjalanan</small><h3><?= (int)($stats['preparing']??0) ?> / <?= (int)($stats['transit']??0) ?></h3></div><div class="card"><small>Sampai / diterima</small><h3><?= (int)($stats['arrived']??0) ?> / <?= (int)($stats['received']??0) ?></h3></div><div class="card"><small>Terlambat / selesai</small><h3><?= (int)($stats['late']??0) ?> / <?= (int)$stats['percent'] ?>%</h3></div></div>
<h3 class="school-section-title">Daftar menu</h3><div class="dist-card"><div class="table-wrap"><table class="tbl"><thead><tr><th>Tanggal</th><th>Menu</th><th>Porsi</th><th>Status</th></tr></thead><tbody><?php foreach($menus as $m): ?><tr><td><?= e($m['delivery_date']) ?></td><td><?= e($m['name']) ?><br><small><?= e($m['description']) ?></small></td><td><?= number_format($m['portions']) ?></td><td><?= e($m['status']) ?></td></tr><?php endforeach; if(!$menus): ?><tr><td colspan="4">Belum ada menu.</td></tr><?php endif; ?></tbody></table></div></div>
<h3 class="school-section-title">Riwayat pengantaran</h3><form class="dist-filter school-history-filter" method="get"><label class="dist-field"><span>Dari tanggal</span><input class="input" type="date" name="from" value="<?= e($from) ?>"></label><label class="dist-field"><span>Sampai tanggal</span><input class="input" type="date" name="to" value="<?= e($to) ?>"></label><select class="input" name="menu"><option value="0">Semua menu</option><?php foreach($menus as $m): ?><option value="<?= $m['id'] ?>" <?= $menuFilter==$m['id']?'selected':'' ?>><?= e($m['name']) ?></option><?php endforeach; ?></select><select class="input" name="delivery_status"><option value="">Semua status</option><?php foreach(['preparing'=>'Dalam Pembuatan','in_transit'=>'Dalam Pengantaran','arrived'=>'Sampai di Sekolah','received'=>'Makanan Diterima'] as $k=>$v): ?><option value="<?= $k ?>" <?= $st===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select><button class="btn">Filter</button></form>
<div class="dist-card"><div class="table-wrap"><table class="tbl"><thead><tr><th>Tanggal</th><th>Menu / porsi</th><th>Status</th><th>Petugas</th><th>Riwayat status</th><th>ETA / aktual</th><th>Catatan</th></tr></thead><tbody><?php foreach($deliveries as $d): $history=DB::all('SELECT status,changed_at,note FROM delivery_status_history WHERE delivery_id=? ORDER BY changed_at',[$d['id']]); ?><tr><td><?= e($d['delivery_date']) ?></td><td><?= e($d['menu_name']) ?> · <?= number_format($d['portions']) ?></td><td><?= e($d['status']) ?></td><td><?= e($d['distributor']) ?></td><td><?php foreach($history as $h): ?><div><?= e($h['status']) ?> · <?= e($h['changed_at']) ?></div><?php endforeach; ?></td><td>ETA: <?= e($d['eta_arrival']?:'Estimasi belum tersedia') ?><br>Aktual: <?= e($d['arrived_at']?:'Belum tiba') ?></td><td><?= e($d['notes']) ?></td></tr><?php endforeach; if(!$deliveries): ?><tr><td colspan="7">Tidak ada data pengiriman sesuai filter.</td></tr><?php endif; ?></tbody></table></div></div>
</section>
